  "Enter your mobile number, email or username": "మీ మొబైల్ నంబర్, ఈమెయిల్ లేదా యూజర్‌నేమ్ ఇవ్వండి",
  "Enter your password": "మీ పాస్‌వర్డ్ ఇవ్వండి",
  "Mobile number, email or username": "మొబైల్ నంబర్, ఈమెయిల్ లేదా యూజర్‌నేమ్",
  "98480 12345 or name@school.in": "98480 12345 లేదా name@school.in",
  "Password": "పాస్‌వర్డ్",
  "Your password": "మీ పాస్‌వర్డ్",
  "Hide password": "పాస్‌వర్డ్ దాచు",
  "Show password": "పాస్‌వర్డ్ చూపించు",
  "We will send a 6-digit code to the mobile number or email on your login. If your role needs two-step login, a second code goes to your other contact. After signing in you can set a new password in My profile.": "మీ లాగిన్‌లోని మొబైల్ నంబర్ లేదా ఈమెయిల్‌కు 6 అంకెల కోడ్ పంపుతాం. మీ పాత్రకు రెండు-దశల లాగిన్ అవసరమైతే, రెండో కోడ్ మీ మరో కాంటాక్ట్‌కు వెళ్తుంది. సైన్ ఇన్ అయ్యాక నా ప్రొఫైల్‌లో కొత్త పాస్‌వర్డ్ పెట్టుకోవచ్చు.",
  "Keep me signed in on this device": "ఈ పరికరంలో నన్ను సైన్ ఇన్‌లో ఉంచు",
  "Checking…": "తనిఖీ చేస్తోంది…",
  "Sign in": "సైన్ ఇన్",
  "Use password instead": "బదులుగా పాస్‌వర్డ్ వాడండి",
  "Forgot password? Sign in with a one-time code": "పాస్‌వర్డ్ మర్చిపోయారా? వన్-టైమ్ కోడ్‌తో సైన్ ఇన్ చేయండి",
  "You were signed out on every device.": "మిమ్మల్ని అన్ని పరికరాల నుండి సైన్ అవుట్ చేశాం.",
  "Your password is set. Sign in with your new password.": "మీ పాస్‌వర్డ్ సెట్ అయింది. కొత్త పాస్‌వర్డ్‌తో సైన్ ఇన్ చేయండి.",
  "Welcome back. Use the details the school office gave you.": "తిరిగి స్వాగతం. స్కూల్ ఆఫీసు ఇచ్చిన వివరాలు వాడండి.",
  "Sign in again": "మళ్ళీ సైన్ ఇన్ చేయండి",
  "We sent a 6-digit code to {to}. It works for 10 minutes.": "{to}కు 6 అంకెల కోడ్ పంపాం. ఇది 10 నిమిషాలు పనిచేస్తుంది.",
  "Shared computer: ask for the code every time.": "పంచుకునే కంప్యూటర్: ప్రతిసారీ కోడ్ అడుగు.",
  "Otherwise this device is remembered and will not ask for a code until you sign out here.": "లేకపోతే ఈ పరికరం గుర్తుంచుకోబడుతుంది, ఇక్కడ సైన్ అవుట్ చేసేవరకు కోడ్ అడగదు.",
  "Verify and sign in": "నిర్ధారించి సైన్ ఇన్ చేయండి",
