  "No signatories yet. Add them on the Document Designs page, with a signature picture if you want it printed.": "ఇంకా సంతకదారులు లేరు. వారిని పత్రాల డిజైన్ల పేజీలో జోడించండి, కావాలంటే సంతకం చిత్రంతో.",
  "At most 3 signatures fit on one document.": "ఒక పత్రంపై గరిష్ఠంగా 3 సంతకాలు పడతాయి.",
  "Footer": "ఫుటర్",
  "Undo changes": "మార్పులు రద్దు చేయండి",
