  "Show": "చూపించు",
  "archived field": "ఆర్కైవ్ అయిన ఖాళీ",
  "Create one below, add its fields, preview it, and publish.": "కింద ఒకటి సృష్టించి, ఖాళీలు జోడించి, ప్రివ్యూ చూసి, విడుదల చేయండి.",
  "← Custom forms": "← కస్టమ్ ఫారాలు",
  "This form is archived. Restore it to change it.": "ఈ ఫారం ఆర్కైవ్‌లో ఉంది. మార్చడానికి తిరిగి తేండి.",
  "You have changes that are not published. People still fill in version": "మీ మార్పులు కొన్ని విడుదల కాలేదు. ప్రజలు ఇంకా ఈ వెర్షన్ నింపుతారు:",
  "until you publish.": "మీరు విడుదల చేసేవరకు.",
  "Published": "విడుదలైంది",
  ". Any change makes a draft until you publish again.": ". ఏ మార్పు అయినా మళ్ళీ విడుదల చేసేవరకు డ్రాఫ్ట్ అవుతుంది.",
  "Add the first field, for example \"Teaching quality\" as a choice of Good, Average, Needs help.": "మొదటి ఖాళీని జోడించండి, ఉదా. \"బోధన నాణ్యత\", బాగుంది, సరాసరి, సాయం కావాలి ఎంపికలతో.",
  "← Forms & Approvals": "← ఫారాలు & ఆమోదాలు",
  "Each step names who approves, as a role or a named person, and up to which amount. A request goes to the first step whose limit covers it. Nobody ever approves their own request; it goes to the next approver. Changes apply to new requests.": "ప్రతి దశ ఎవరు ఆమోదిస్తారో చెబుతుంది, పాత్రగా లేదా పేరున్న వ్యక్తిగా, ఏ మొత్తం వరకో. అభ్యర్థన దాని పరిమితి సరిపోయే మొదటి దశకు వెళ్తుంది. ఎవరూ తమ సొంత అభ్యర్థనను ఆమోదించరు; అది తదుపరి ఆమోదకుడికి వెళ్తుంది. మార్పులు కొత్త అభ్యర్థనలకు వర్తిస్తాయి.",
