  "Connect each channel to a provider. Keys are stored encrypted and never shown again. What each message says is in": "ప్రతి ఛానల్‌ను ఒక ప్రొవైడర్‌తో కలపండి. కీలు ఎన్‌క్రిప్ట్ చేసి ఉంచుతారు, మళ్ళీ ఎప్పుడూ చూపించరు. ప్రతి మెసేజ్ ఏమి చెబుతుందో ఇక్కడ ఉంది:",
