  ". Buy more from the provider and add them below.": ". ప్రొవైడర్ నుండి ఇంకా కొని కింద జోడించండి.",
  "SMS cannot be switched on until both are added.": "రెండూ జోడించేవరకు SMS ఆన్ చేయలేరు.",
  "credits left": "క్రెడిట్‌లు మిగిలాయి",
