  "No credits added or used yet.": "ఇంకా క్రెడిట్‌లు జోడించలేదు, వాడలేదు.",
  "Always on": "ఎప్పుడూ ఆన్",
  ". These hold the school's core records, so they cannot be switched off.": ". వీటిలో స్కూల్ ప్రధాన రికార్డులు ఉంటాయి, కాబట్టి ఆపలేరు.",
