  "Switch on the AI assistant first. While it is off, every feature is off.": "ముందుగా AI సహాయకుడిని ఆన్ చేయండి. అది ఆఫ్‌లో ఉన్నంత వరకు ప్రతి సదుపాయం ఆఫ్.",
  "Error": "లోపం",
  "An integration failed its last test. Open it to fix the details.": "ఒక అనుసంధానం తన చివరి పరీక్షలో విఫలమైంది. వివరాలు సరిచేయడానికి దాన్ని తెరవండి.",
  "Arrives in Stage": "ఈ దశలో వస్తుంది:",
  "disappears from the menu, search and dashboards for everyone. Nothing is deleted: switch it on again and everything is back.": "అందరికీ మెనూ, వెతుకులాట, డాష్‌బోర్డుల నుండి కనిపించదు. ఏదీ తొలగించబడదు: మళ్ళీ ఆన్ చేస్తే అంతా తిరిగి వస్తుంది.",
