  "A template only switches modules on, never off. Settings you have already chosen are kept unless you tick the box below.": "టెంప్లేట్ మాడ్యూల్స్‌ను ఆన్ మాత్రమే చేస్తుంది, ఎప్పుడూ ఆఫ్ చేయదు. మీరు ఎంచుకున్న సెట్టింగ్‌లు ఉంటాయి, కింద బాక్స్ టిక్ చేస్తే తప్ప.",
  "Modules switched on": "ఆన్ అయిన మాడ్యూల్స్",
