  "Last checked": "చివరిగా తనిఖీ చేసింది",
  "School OS stops using": "School OS దీన్ని వాడటం ఆపుతుంది:",
  ". The saved details and keys are removed; you will need them again to reconnect.": ". సేవ్ చేసిన వివరాలు, కీలు తొలగిస్తారు; మళ్ళీ కలపడానికి అవి మళ్ళీ కావాలి.",
  "Saving tests the details straight away.": "సేవ్ చేయగానే వివరాలు వెంటనే పరీక్షిస్తారు.",
  "Save and test": "సేవ్ చేసి పరీక్షించండి",
  "Environment": "వాతావరణం",
  "Webhook address": "వెబ్‌హుక్ చిరునామా",
  "Add this address in": "ఈ చిరునామాను ఇక్కడ జోడించండి:",
  "so payments it confirms reach School OS. It is filled for you and cannot be changed.": "తద్వారా అది నిర్ధారించే చెల్లింపులు School OSకు చేరతాయి. ఇది మీ కోసం నింపారు, మార్చలేరు.",
  "Test these details": "ఈ వివరాలు పరీక్షించండి",
  "A new gateway starts switched off. Switch it on after a test passes.": "కొత్త గేట్‌వే ఆఫ్‌లో మొదలవుతుంది. పరీక్ష పాస్ అయ్యాక ఆన్ చేయండి.",
  "Add a gateway": "గేట్‌వే జోడించండి",
  "Connect Razorpay and other gateways so parents can pay online. Which class or fee head uses which gateway is set in Fee Management, Fee Settings.": "తల్లిదండ్రులు ఆన్‌లైన్‌లో చెల్లించేలా Razorpay, ఇతర గేట్‌వేలను కలపండి. ఏ తరగతి లేదా ఫీజు హెడ్ ఏ గేట్‌వే వాడాలో ఫీజుల నిర్వహణ, ఫీజు సెట్టింగ్‌లలో నిర్ణయిస్తారు.",
  "Parents cannot pay online yet. Open a gateway, test it, then switch it on.": "తల్లిదండ్రులు ఇంకా ఆన్‌లైన్‌లో చెల్లించలేరు. ఒక గేట్‌వే తెరిచి, పరీక్షించి, ఆన్ చేయండి.",
  "Archived": "ఆర్కైవ్ అయింది",
  "Active": "చురుకుగా ఉంది",
  "Inactive": "నిష్క్రియం",
  "Test": "పరీక్ష",
  "Not tested": "పరీక్షించలేదు",
  "Parents can pay at the counter in cash, UPI or cheque from day one. To take fees online, connect Razorpay (recommended) or another gateway.": "తల్లిదండ్రులు మొదటి రోజు నుండే కౌంటర్‌లో నగదు, UPI లేదా చెక్కుతో చెల్లించవచ్చు. ఆన్‌లైన్‌లో ఫీజు తీసుకోవడానికి Razorpay (సిఫార్సు) లేదా మరో గేట్‌వేను కలపండి.",
  "Test connection": "కనెక్షన్ పరీక్షించండి",
  "Switch on becomes available after a test passes.": "పరీక్ష పాస్ అయ్యాక ఆన్ చేసే అవకాశం వస్తుంది.",
  "The gateway is switched off and hidden. Payments already made through it keep their record. You can restore it later.": "గేట్‌వే ఆఫ్ చేసి దాచారు. దాని ద్వారా జరిగిన చెల్లింపుల రికార్డు ఉంటుంది. తర్వాత తిరిగి తేవచ్చు.",
  "Restore": "తిరిగి తేండి",
  "Add bank account": "బ్యాంక్ ఖాతా జోడించండి",
  "Online payments will no longer be split into": "ఆన్‌లైన్ చెల్లింపులు ఇక దీనిలోకి విభజించబడవు:",
  ". Fee heads linked to it will need another account in Fee Settings. Payments already made keep their account.": ". దీనికి కలిపిన ఫీజు హెడ్‌లకు ఫీజు సెట్టింగ్‌లలో మరో ఖాతా కావాలి. ఇప్పటికే జరిగిన చెల్లింపుల ఖాతా అదే ఉంటుంది.",
  "It takes no payments. Payments already made through it keep their record.": "ఇది చెల్లింపులు తీసుకోదు. దాని ద్వారా జరిగిన చెల్లింపుల రికార్డు ఉంటుంది.",
  "Payments through this gateway are pretend payments. Switch to live mode when Razorpay has activated your account.": "ఈ గేట్‌వే ద్వారా చెల్లింపులు పరీక్ష చెల్లింపులు. Razorpay మీ ఖాతాను యాక్టివేట్ చేశాక లైవ్ మోడ్‌కు మారండి.",
  "No bank account added. All online payments go to the main account linked to your Razorpay account.": "బ్యాంక్ ఖాతా జోడించలేదు. అన్ని ఆన్‌లైన్ చెల్లింపులు మీ Razorpay ఖాతాకు కలిపిన ప్రధాన ఖాతాకు వెళ్తాయి.",
  "· account ending": "· చివరి అంకెలు",
  "Add a bank account": "బ్యాంక్ ఖాతా జోడించండి",
  "No changes yet.": "ఇంకా మార్పులు లేవు.",
