  "will appear again in campus choices across School OS.": "School OS అంతటా క్యాంపస్ ఎంపికల్లో మళ్ళీ కనిపిస్తుంది.",
  "The main campus is the default for new records and documents.": "కొత్త రికార్డులు, పత్రాలకు ప్రధాన క్యాంపసే డిఫాల్ట్.",
  "It drops out of campus choices. A campus that still has students, staff, academic years or logins cannot be archived. You can restore it later.": "ఇది క్యాంపస్ ఎంపికల నుండి తొలగుతుంది. ఇంకా విద్యార్థులు, సిబ్బంది, విద్యా సంవత్సరాలు లేదా లాగిన్‌లు ఉన్న క్యాంపస్‌ను ఆర్కైవ్ చేయలేరు. తర్వాత తిరిగి తేవచ్చు.",
