  "Upload, check the matched columns and every row, fix or leave out the rows with problems, then bring in the rest. Nothing is saved before that.": "అప్‌లోడ్ చేసి, సరిపోల్చిన నిలువు వరుసలు, ప్రతి వరుస తనిఖీ చేసి, సమస్యల వరుసలు సరిచేసి లేదా వదిలేసి, మిగతావి తీసుకురండి. అంతకు ముందు ఏదీ సేవ్ కాదు.",
