  "Parents it shows": "అది చూపించే తల్లిదండ్రులు",
  "Go-live date": "గో-లైవ్ తేదీ",
  "The first day School OS is your record. Any day of the year works. Fees due before it belong to the old software, and finance records start on it.": "School OS మీ రికార్డు అయ్యే మొదటి రోజు. సంవత్సరంలో ఏ రోజైనా సరే. దానికి ముందు బాకీ ఫీజు పాత సాఫ్ట్‌వేర్‌ది, ఆర్థిక రికార్డులు ఆ రోజు నుండి మొదలవుతాయి.",
  "Switching to School OS · Data Backup & Security": "School OSకు మారడం · డేటా బ్యాకప్ & భద్రత",
  "Set this year's fee structures": "ఈ సంవత్సరం ఫీజు నిర్మాణాలు ఏర్పాటు చేయండి",
  "The Accountant sets each class's fees for this year before bringing in old dues, so dues and receipts land on the right fee heads.": "పాత బాకీలు తెచ్చే ముందు అకౌంటెంట్ ఈ సంవత్సరం ప్రతి తరగతి ఫీజు ఏర్పాటు చేస్తారు, తద్వారా బాకీలు, రసీదులు సరైన ఫీజు హెడ్‌లపై పడతాయి.",
  "Opening cash and bank balances": "ప్రారంభ నగదు, బ్యాంక్ నిల్వలు",
  "The Accountant enters the cash book and each bank account on the go-live date, and the financial year (April to March unless changed).": "అకౌంటెంట్ గో-లైవ్ తేదీ నాటి క్యాష్ బుక్, ప్రతి బ్యాంక్ ఖాతా నమోదు చేస్తారు, ఆర్థిక సంవత్సరం కూడా (మార్చకపోతే ఏప్రిల్ నుండి మార్చి).",
  "Your school is moving in.": "మీ స్కూల్ School OSకు మారుతోంది.",
  "Your move to School OS": "School OSకు మీ మార్పు",
  "Bring in what your old software, Excel sheets or registers hold, in this order. You can start on any day of the year.": "మీ పాత సాఫ్ట్‌వేర్, Excel షీట్లు లేదా రిజిస్టర్లలో ఉన్నది ఈ క్రమంలో తీసుకురండి. సంవత్సరంలో ఏ రోజైనా మొదలుపెట్టవచ్చు.",
  "Set up the school year": "స్కూల్ సంవత్సరం ఏర్పాటు చేయండి",
  "Check and go live": "తనిఖీ చేసి గో లైవ్ చేయండి",
  "Bring in a file": "ఫైల్ తీసుకురండి",
  "School OS finds the headings, works out what the file holds, matches the columns and tidies dates, phones and names. You check every row before anything is saved.": "School OS శీర్షికలు కనుగొని, ఫైల్‌లో ఏముందో అర్థం చేసుకుని, నిలువు వరుసలు సరిపోల్చి, తేదీలు, ఫోన్లు, పేర్లు సరిచేస్తుంది. ఏదైనా సేవ్ చేసే ముందు ప్రతి వరుసను మీరు తనిఖీ చేస్తారు.",
  "No files yet": "ఇంకా ఫైళ్ళు లేవు",
  "Go live on School OS?": "School OSలో గో లైవ్ చేయాలా?",
  "Go live and send Parent Links": "గో లైవ్ చేసి పేరెంట్ లింక్‌లు పంపండి",
  "Check a file · Switching to School OS": "ఫైల్ తనిఖీ · School OSకు మారడం",
