  "The design could not be read. Reload the page.": "డిజైన్‌ను చదవలేకపోయాం. పేజీని మళ్ళీ లోడ్ చేయండి.",
  "Choose a ready design.": "సిద్ధమైన డిజైన్ ఎంచుకోండి.",
  "The preview could not be made. Your changes are still here. Try again.": "ప్రివ్యూ తయారు కాలేదు. మీ మార్పులు ఇంకా ఇక్కడే ఉన్నాయి. మళ్ళీ ప్రయత్నించండి.",
  "The design could not be read. Reload the page and try again.": "డిజైన్‌ను చదవలేకపోయాం. పేజీని మళ్ళీ లోడ్ చేసి ప్రయత్నించండి.",
  "That did not save. Your changes are still here. Try again.": "సేవ్ కాలేదు. మీ మార్పులు ఇంకా ఇక్కడే ఉన్నాయి. మళ్ళీ ప్రయత్నించండి.",
  "Choose a picture to upload.": "అప్‌లోడ్ చేయడానికి చిత్రం ఎంచుకోండి.",
  "That did not save. Try again.": "సేవ్ కాలేదు. మళ్ళీ ప్రయత్నించండి.",
  "Signatories": "సంతకదారులు",
  "People who sign documents. Add a picture of the signature to print it; otherwise a line is left to sign by hand.": "పత్రాలపై సంతకం చేసేవారు. ప్రింట్ చేయడానికి సంతకం చిత్రం జోడించండి; లేకపోతే చేతితో సంతకానికి ఒక గీత వదులుతారు.",
  "Name": "పేరు",
  "Lakshmi Rao": "లక్ష్మీ రావు",
