  "This campus was not found.": "ఈ క్యాంపస్ దొరకలేదు.",
  "This campus is not archived.": "ఈ క్యాంపస్ ఆర్కైవ్‌లో లేదు.",
  "Ask and Do": "అడగండి, చేయండి",
  "Questions in your own words. Ready-made questions per role and typed words such as \"absent today\" or \"fees due class 5\" work without AI. With this on, when the words match no ready-made question, the AI service picks the closest one from the words only; the answer always comes from the school's own lists. Preparing actions as a filled form (Do) is not built yet.": "మీ సొంత మాటల్లో ప్రశ్నలు. ప్రతి పాత్రకు సిద్ధమైన ప్రశ్నలు, \"ఈరోజు గైర్హాజరు\" లేదా \"5వ తరగతి బాకీ ఫీజు\" వంటి మాటలు AI లేకుండానే పనిచేస్తాయి. ఇది ఆన్‌లో ఉంటే, మాటలు ఏ సిద్ధమైన ప్రశ్నకూ సరిపోలకపోతే, AI సేవ మాటల ఆధారంగానే దగ్గరి ప్రశ్నను ఎంచుకుంటుంది; జవాబు ఎప్పుడూ స్కూల్ సొంత జాబితాల నుండే వస్తుంది. పనులను నింపిన ఫారంగా సిద్ధం చేయడం (చేయండి) ఇంకా తయారు కాలేదు.",
  "Smart Import": "స్మార్ట్ దిగుమతి",
  "When importing a spreadsheet, suggests which column is which and likely fixes (dates, phone numbers, class names). With the AI service connected, it also suggests columns the rules could not match, from the headings only. You tick each suggestion before it is used.": "స్ప్రెడ్‌షీట్ దిగుమతి చేసేటప్పుడు ఏ నిలువు వరుస ఏమిటో, సంభావ్య సవరణలు (తేదీలు, ఫోన్ నంబర్లు, తరగతి పేర్లు) సూచిస్తుంది. AI సేవ కలిపి ఉంటే, నియమాలు సరిపోల్చలేని నిలువు వరుసలను కూడా శీర్షికల ఆధారంగా సూచిస్తుంది. ప్రతి సూచనను వాడే ముందు మీరు టిక్ చేస్తారు.",
  "AI auto-reply to enquiries": "విచారణలకు AI ఆటో-రిప్లై",
  "Suggests replies to admission enquiries; a person sends them.": "ప్రవేశ విచారణలకు జవాబులు సూచిస్తుంది; పంపేది ఒక వ్యక్తి.",
  "Student insights and early warnings": "విద్యార్థుల అవగాహన, ముందస్తు హెచ్చరికలు",
  "Flags students whose attendance, marks or fees need attention.": "హాజరు, మార్కులు లేదా ఫీజుపై దృష్టి అవసరమైన విద్యార్థులను గుర్తిస్తుంది.",
  "Forecasts": "అంచనాలు",
  "Looking ahead from the school's own records: attendance and marks heading below the line, fees likely to come late, seats likely to stay empty, staff and cash.": "స్కూల్ సొంత రికార్డుల నుండి ముందు చూపు: గీత కంటే కిందకు వెళ్తున్న హాజరు, మార్కులు, ఆలస్యంగా వచ్చే ఫీజు, ఖాళీగా ఉండే సీట్లు, సిబ్బంది, నగదు.",
  "Principal summary": "ప్రిన్సిపల్ సారాంశం",
  "Today's brief for the Principal and School Admin each school morning, and the weekly brief on Monday: what happened, what may need them next and what waits for their decision. Every number is the school's own record, with a link to the list behind it.": "ప్రతి స్కూల్ ఉదయం ప్రిన్సిపల్, స్కూల్ అడ్మిన్ కోసం ఈరోజు సారాంశం, సోమవారం వారపు సారాంశం: ఏం జరిగింది, తర్వాత వారికి ఏం అవసరం, వారి నిర్ణయం కోసం ఏం వేచి ఉంది. ప్రతి సంఖ్య స్కూల్ సొంత రికార్డు, దాని వెనుక జాబితా లింక్‌తో.",
  "Teacher assistant": "ఉపాధ్యాయ సహాయకుడు",
  "Drafts homework, feedback on submissions and report card remarks for the teacher to edit.": "ఉపాధ్యాయుడు సవరించడానికి హోంవర్క్, సమర్పణలపై అభిప్రాయం, రిపోర్ట్ కార్డు వ్యాఖ్యల డ్రాఫ్ట్‌లు తయారు చేస్తుంది.",
  "AI question papers": "AI ప్రశ్నపత్రాలు",
  "Not built: free tools already do this.": "తయారు చేయలేదు: ఉచిత సాధనాలు ఇప్పటికే ఇది చేస్తాయి.",
  "Translation of typed messages": "టైప్ చేసిన మెసేజ్‌ల అనువాదం",
  "Translates a typed message into each parent's language. The sender sees and can edit each translation; the parent's copy says \"Translated from English\".": "టైప్ చేసిన మెసేజ్‌ను ప్రతి తల్లిదండ్రి భాషలోకి అనువదిస్తుంది. పంపేవారు ప్రతి అనువాదాన్ని చూసి సవరించవచ్చు; తల్లిదండ్రి కాపీపై \"Translated from English\" అని ఉంటుంది.",
  "A CBSE school where children go home each day, with a library and school buses.": "పిల్లలు రోజూ ఇంటికి వెళ్ళే CBSE స్కూల్, గ్రంథాలయం, స్కూల్ బస్సులతో.",
  "A state board school with a library.": "గ్రంథాలయం ఉన్న రాష్ట్ర బోర్డు స్కూల్.",
  "Children live at school: hostel, library and store.": "పిల్లలు స్కూల్‌లోనే ఉంటారు: హాస్టల్, గ్రంథాలయం, స్టోర్.",
  "Nursery to UKG, with school vans.": "నర్సరీ నుండి UKG, స్కూల్ వ్యాన్లతో.",
  "Google Workspace for staff email, calendars and Classroom.": "సిబ్బంది ఈమెయిల్, క్యాలెండర్లు, Classroom కోసం Google Workspace.",
