  "Message history": "మెసేజ్ చరిత్ర",
  "This kind of record is not known.": "ఈ రకం రికార్డు తెలియదు.",
  "Choose between 1 month and 100 years, or keep for as long as the school uses School OS.": "1 నెల నుండి 100 సంవత్సరాల మధ్య ఎంచుకోండి, లేదా స్కూల్ School OS వాడుతున్నంత కాలం ఉంచండి.",
  "Phone numbers, email and address": "ఫోన్ నంబర్లు, ఈమెయిల్, చిరునామా",
  "Aadhaar, PAN, APAAR and other ID numbers": "ఆధార్, PAN, APAAR, ఇతర ID నంబర్లు",
  "Photos": "ఫోటోలు",
  "Date of birth, religion, category, health notes and other personal details": "పుట్టిన తేదీ, మతం, వర్గం, ఆరోగ్య గమనికలు, ఇతర వ్యక్తిగత వివరాలు",
  "Name (replaced with \"Removed person\")": "పేరు (\"తొలగించిన వ్యక్తి\"తో మారుస్తారు)",
  "Choose the person whose data should be removed.": "ఎవరి డేటా తొలగించాలో ఆ వ్యక్తిని ఎంచుకోండి.",
  "Give the reason in a few words, so the approver knows why.": "ఆమోదకుడికి తెలిసేలా కొన్ని మాటల్లో కారణం చెప్పండి.",
  "Say who asked, for example \"Father, by letter\".": "ఎవరు అడిగారో చెప్పండి, ఉదా. \"తండ్రి, లేఖ ద్వారా\".",
  "This invite link has expired or was already used. Ask your School Admin for a new one.": "ఈ ఆహ్వాన లింక్ గడువు ముగిసింది లేదా ఇప్పటికే వాడారు. మీ స్కూల్ అడ్మిన్‌ను కొత్తది అడగండి.",
  "Choose a new password, not the temporary one your school gave you.": "కొత్త పాస్‌వర్డ్ ఎంచుకోండి, స్కూల్ ఇచ్చిన తాత్కాలికది కాదు.",
  "Send a new code first.": "ముందు కొత్త కోడ్ పంపండి.",
  "This code has been used or replaced. Send a new code.": "ఈ కోడ్ వాడారు లేదా మార్చారు. కొత్త కోడ్ పంపండి.",
  "This code has expired after 10 minutes. Send a new code.": "10 నిమిషాల తర్వాత ఈ కోడ్ గడువు ముగిసింది. కొత్త కోడ్ పంపండి.",
  "Too many wrong codes. Send a new code.": "చాలాసార్లు తప్పు కోడ్. కొత్త కోడ్ పంపండి.",
  "This code has already been used. Send a new code.": "ఈ కోడ్ ఇప్పటికే వాడారు. కొత్త కోడ్ పంపండి.",
  "1 hour": "1 గంట",
  "4 hours": "4 గంటలు",
  "Go to today": "ఈ రోజుకు వెళ్ళండి",
  "Attendance can be taken for today or earlier days.": "హాజరు ఈ రోజు లేదా ముందు రోజులకు తీసుకోవచ్చు.",
  "If the school opens that day, turn on \"allow attendance\" for the date in the School Calendar.": "ఆ రోజు స్కూల్ తెరిస్తే, స్కూల్ క్యాలెండర్‌లో ఆ తేదీకి \"హాజరు అనుమతించు\" ఆన్ చేయండి.",
  "Holidays, Sundays and days off are left out of every %, report and register total.": "సెలవులు, ఆదివారాలు మరియు విరామ రోజులు ప్రతి %, నివేదిక మరియు రిజిస్టర్ మొత్తం నుండి తీసివేయబడతాయి.",
  "Open the register": "రిజిస్టర్ తెరవండి",
  "Open Student Management": "విద్యార్థి నిర్వహణ తెరవండి",
  "Students appear here once they are placed in this section in Student Management.": "విద్యార్థి నిర్వహణలో ఈ సెక్షన్‌లో ఉంచిన తర్వాత విద్యార్థులు ఇక్కడ కనిపిస్తారు.",
  "A class not marked by": "ఈ సమయానికి గుర్తించని తరగతి",
  "shows as not taken, and no absence message goes to parents. Remind sends the class teacher a message in the app.": "తీసుకోలేదు అని చూపుతుంది, తల్లిదండ్రులకు గైర్హాజరు సందేశం వెళ్ళదు. గుర్తుచేయండి యాప్‌లో క్లాస్ టీచర్‌కు సందేశం పంపుతుంది.",
  "Holidays and Sundays are never counted. Choose another date.": "సెలవులు మరియు ఆదివారాలు ఎప్పుడూ లెక్కించబడవు. మరో తేదీ ఎంచుకోండి.",
  "Sections appear here once they have students.": "విద్యార్థులు ఉన్న తర్వాత సెక్షన్లు ఇక్కడ కనిపిస్తాయి.",
  "students": "విద్యార్థులు",
  "Green is 92% or more, amber 85% to 92%, red below 85%. Late counts as present; leave, holidays and Sundays are not counted.": "ఆకుపచ్చ 92% లేదా ఎక్కువ, పసుపు 85% నుండి 92%, ఎరుపు 85% కంటే తక్కువ. ఆలస్యం హాజరుగా లెక్కించబడుతుంది; సెలవు, పండుగ సెలవులు మరియు ఆదివారాలు లెక్కించబడవు.",
