  "No sections are set up for this academic year yet. Add them in Academic Setup.": "ఈ విద్యా సంవత్సరానికి ఇంకా సెక్షన్లు సెట్ కాలేదు. అకడమిక్ సెటప్‌లో జోడించండి.",
  "Open Attendance Settings": "హాజరు సెట్టింగ్‌లు తెరవండి",
  "Setting a reason does not change the mark or the attendance %. Every change is kept in the audit log.": "కారణం పెట్టడం గుర్తును లేదా హాజరు %ను మార్చదు. ప్రతి మార్పు ఆడిట్ లాగ్‌లో ఉంచబడుతుంది.",
  "Back to the": "తిరిగి",
  "Only HR, the School Admin or the Principal can correct staff attendance. Ask them if your own attendance is wrong.": "HR, స్కూల్ అడ్మిన్ లేదా ప్రిన్సిపాల్ మాత్రమే సిబ్బంది హాజరు సరిచేయగలరు. మీ హాజరు తప్పుగా ఉంటే వారిని అడగండి.",
  "You are not class teacher or subject teacher of any section this year.": "ఈ సంవత్సరం మీరు ఏ సెక్షన్‌కూ క్లాస్ టీచర్ లేదా సబ్జెక్ట్ టీచర్ కాదు.",
  "Corrections are only for days attendance is taken.": "సవరణలు హాజరు తీసుకునే రోజులకు మాత్రమే.",
