  "Attendance reports are for teachers of a class, HR, the School Admin and the Principal.": "హాజరు నివేదికలు తరగతి టీచర్లు, HR, స్కూల్ అడ్మిన్ మరియు ప్రిన్సిపాల్ కోసం.",
