  "Add a shift, such as Morning 7:00 AM to 1:00 PM, then assign staff to it.": "ఉదయం 7:00 నుండి మధ్యాహ్నం 1:00 వంటి షిఫ్ట్ జోడించి, సిబ్బందిని దానికి కేటాయించండి.",
