  "Take attendance in every period of the Time Table, not once a day.": "టైమ్ టేబుల్ ప్రతి పీరియడ్‌లో హాజరు తీసుకోండి, రోజుకు ఒకసారి కాదు.",
  "Offline mode": "ఆఫ్‌లైన్ మోడ్",
  "Teachers can take attendance without internet. It is kept on the phone and sent when online.": "టీచర్లు ఇంటర్నెట్ లేకుండా హాజరు తీసుకోవచ్చు. ఇది ఫోన్‌లో ఉంచబడి ఆన్‌లైన్ అయినప్పుడు పంపబడుతుంది.",
  "Face, fingerprint, RFID card and iris machines send punches to School OS.": "ముఖం, వేలిముద్ర, RFID కార్డ్ మరియు ఐరిస్ యంత్రాలు School OSకు పంచ్‌లు పంపుతాయి.",
  "Staff and students scan a QR at the entrance with their phone.": "సిబ్బంది మరియు విద్యార్థులు తమ ఫోన్‌తో ప్రవేశ ద్వారం వద్ద QR స్కాన్ చేస్తారు.",
  "Mobile check-in": "మొబైల్ చెక్-ఇన్",
