  "Student leave balances": "విద్యార్థి సెలవు బ్యాలెన్స్‌లు",
  "A limit of days per leave type for a term or year, like 6 medical days a term.": "టర్మ్ లేదా సంవత్సరానికి ప్రతి సెలవు రకానికి రోజుల పరిమితి, టర్మ్‌కు 6 వైద్య రోజులు లాగా.",
  "Different working hours for groups of staff.": "సిబ్బంది సమూహాలకు వేర్వేరు పని గంటలు.",
  "Record extra hours staff worked, for salary.": "జీతం కోసం సిబ్బంది పనిచేసిన అదనపు గంటలు నమోదు చేయండి.",
  "Record why a student was absent: sick, family function, travel, fees dispute, not known yet or other. Shown in the register, reports and Early Warnings.": "విద్యార్థి ఎందుకు గైర్హాజరయ్యారో నమోదు చేయండి: అనారోగ్యం, కుటుంబ కార్యక్రమం, ప్రయాణం, ఫీజు వివాదం, ఇంకా తెలియదు లేదా ఇతర. రిజిస్టర్, నివేదికలు మరియు ముందస్తు హెచ్చరికలలో చూపబడుతుంది.",
