  ". Paid": ". చెల్లించారు",
  "Not a student yet, so this fee stays on the application with its own receipts. It goes into the Day Book under Other fee types, Application fee.": "ఇంకా విద్యార్థి కాదు, కాబట్టి ఈ ఫీజు దాని రసీదులతో దరఖాస్తుపై ఉంటుంది. ఇది డే బుక్‌లో ఇతర ఫీజు రకాలు, దరఖాస్తు ఫీజులోకి వెళ్తుంది.",
  "To cancel a receipt, the Principal or School Admin opens the application in Admission Management.": "రసీదు రద్దు చేయడానికి, ప్రిన్సిపాల్ లేదా స్కూల్ అడ్మిన్ ప్రవేశాల నిర్వహణలో దరఖాస్తు తెరుస్తారు.",
  "Import old dues and receipts": "పాత బాకీలు మరియు రసీదులు దిగుమతి చేయండి",
  "Fee invoice": "ఫీజు ఇన్వాయిస్",
  "overdue": "గడువు దాటింది",
  "due": "చెల్లించాలి",
  "Change student": "విద్యార్థిని మార్చండి",
  "Year total · paid · balance now": "సంవత్సర మొత్తం · చెల్లించింది · ఇప్పుడు బ్యాలెన్స్",
  "Balance includes late fees and dues raised so far": "బ్యాలెన్స్‌లో ఇప్పటివరకు వేసిన ఆలస్య రుసుములు మరియు బాకీలు ఉన్నాయి",
  "Statement with running balance": "నడుస్తున్న బ్యాలెన్స్‌తో స్టేట్‌మెంట్",
  "Entry": "నమోదు",
  "Reference": "రిఫరెన్స్",
  "Charged": "వేసినది",
  "Paid or reduced": "చెల్లించినది లేదా తగ్గించినది",
  "Balance brought forward": "ముందుకు తెచ్చిన బ్యాలెన్స్",
  "Balance on": "ఈ తేదీన బ్యాలెన్స్",
  "Brought forward ·": "ముందుకు తెచ్చినది ·",
