  "One of the chosen rows was paid or changed a moment ago. Check the dues and try again.": "ఎంచుకున్న వరుసలలో ఒకటి ఇప్పుడే చెల్లించబడింది లేదా మార్చబడింది. బాకీలు తనిఖీ చేసి మళ్ళీ ప్రయత్నించండి.",
  "Tick at least one row to pay.": "చెల్లించడానికి కనీసం ఒక వరుస టిక్ చేయండి.",
  "Only late fee rows can be waived here. Use a concession for other rows.": "ఇక్కడ ఆలస్య రుసుము వరుసలు మాత్రమే మాఫీ చేయవచ్చు. ఇతర వరుసలకు రాయితీ వాడండి.",
  "Waiving a late fee needs the \"waive late fee\" permission.": "ఆలస్య రుసుము మాఫీకి \"ఆలస్య రుసుము మాఫీ\" అనుమతి అవసరం.",
  "Give a reason of at least 5 characters for the waiver.": "మాఫీకి కనీసం 5 అక్షరాల కారణం ఇవ్వండి.",
  "Nothing is left to pay on the ticked rows.": "టిక్ చేసిన వరుసలపై చెల్లించడానికి ఏమీ మిగలలేదు.",
  "Could not find a free receipt number": "ఖాళీ రసీదు నంబర్ కనబడలేదు",
  "This payment is cancelled, so it cannot be posted.": "ఈ చెల్లింపు రద్దు అయింది, కాబట్టి పోస్ట్ చేయలేము.",
  "DREAM TEAM support access cannot cancel payments. Ask the school’s accountant.": "DREAM TEAM సపోర్ట్ యాక్సెస్ చెల్లింపులను రద్దు చేయలేదు. స్కూల్ అకౌంటెంట్‌ను అడగండి.",
  "Choose the reason for cancelling.": "రద్దుకు కారణం ఎంచుకోండి.",
  "Say what happened in the note (at least 5 characters).": "ఏమి జరిగిందో నోట్‌లో చెప్పండి (కనీసం 5 అక్షరాలు).",
  "This payment was not found.": "ఈ చెల్లింపు కనబడలేదు.",
  "This payment is already cancelled.": "ఈ చెల్లింపు ఇప్పటికే రద్దు అయింది.",
  "This payment is waiting for verification. Reject it in Approvals instead.": "ఈ చెల్లింపు తనిఖీ కోసం వేచి ఉంది. బదులుగా ఆమోదాలలో తిరస్కరించండి.",
  "This online payment failed, so there is nothing to cancel.": "ఈ ఆన్‌లైన్ చెల్లింపు విఫలమైంది, కాబట్టి రద్దు చేయడానికి ఏమీ లేదు.",
  "Cancelling this payment is already waiting for approval.": "ఈ చెల్లింపు రద్దు ఇప్పటికే ఆమోదం కోసం వేచి ఉంది.",
  "This payment has a refund, so it cannot be cancelled. Record the correction as an adjustment instead.": "ఈ చెల్లింపుపై రీఫండ్ ఉంది, కాబట్టి రద్దు చేయలేము. బదులుగా సవరణను సర్దుబాటుగా నమోదు చేయండి.",
