  "students in this list, with the filters shown. Logged in the export log.": "ఈ జాబితాలోని విద్యార్థులు, చూపిన ఫిల్టర్‌లతో. ఎగుమతి లాగ్‌లో నమోదవుతుంది.",
  "Students have no class until the year is opened in": "సంవత్సరం ఇక్కడ తెరిచే వరకు విద్యార్థులకు తరగతి ఉండదు:",
