  "Counselling and career guidance are optional. Switch them on in": "కౌన్సెలింగ్ మరియు కెరీర్ మార్గదర్శనం ఐచ్ఛికం. వీటిని ఇక్కడ ఆన్ చేయండి:",
  "Refer to counselling": "కౌన్సెలింగ్‌కు పంపండి",
  "It leaves the behaviour timeline. Points it gave are reversed with a new entry; nothing is deleted.": "ఇది ప్రవర్తన టైమ్‌లైన్ నుండి తొలగిపోతుంది. ఇది ఇచ్చిన పాయింట్లు కొత్త నమోదుతో వెనక్కి తీసుకోబడతాయి; ఏదీ తొలగించబడదు.",
