  "Private: confidential notes recorded (only the Counsellor can read them)": "ప్రైవేట్: గోప్య నోట్స్ నమోదయ్యాయి (కౌన్సెలర్ మాత్రమే చదవగలరు)",
  "The behaviour record": "ప్రవర్తన రికార్డ్",
  "Opens a counselling case and tells the counsellor. What the counsellor writes stays private to them.": "కౌన్సెలింగ్ కేసు తెరిచి కౌన్సెలర్‌కు తెలియజేస్తుంది. కౌన్సెలర్ రాసేది వారికి మాత్రమే ప్రైవేట్‌గా ఉంటుంది.",
  "No one has the Counsellor role yet. The case is opened and can be given to a counsellor later (Settings, Users & Permissions).": "ఇంకా ఎవరికీ కౌన్సెలర్ పాత్ర లేదు. కేసు తెరవబడుతుంది, తర్వాత కౌన్సెలర్‌కు ఇవ్వవచ్చు (సెట్టింగ్‌లు, యూజర్లు & అనుమతులు).",
  "Suspension": "సస్పెన్షన్",
