  "Also for a warning, a suspension, a reward or recognition.": "హెచ్చరిక, సస్పెన్షన్, బహుమతి లేదా గుర్తింపు కోసం కూడా.",
  "Photos are made smaller for phones. Students who already have a photo keep it unless you choose to replace it.": "ఫోన్ల కోసం ఫోటోలు చిన్నవి చేయబడతాయి. ఇప్పటికే ఫోటో ఉన్న విద్యార్థులకు మీరు మార్చాలని ఎంచుకుంటే తప్ప అదే ఉంటుంది.",
  "Name each file by the admission number, for example SPS-2026-0145.jpg. Up to 200 photos at a time.": "ప్రతి ఫైల్‌కు అడ్మిషన్ నంబర్ పేరు పెట్టండి, ఉదాహరణకు SPS-2026-0145.jpg. ఒకసారి 200 ఫోటోల వరకు.",
  "Has a photo": "ఫోటో ఉంది",
  "Skip": "వదిలేయండి",
  "Replace photos students already have": "విద్యార్థులకు ఇప్పటికే ఉన్న ఫోటోలను మార్చండి",
