  "Approved. Press Issue to print it.": "ఆమోదించబడింది. ప్రింట్ చేయడానికి జారీ చేయండి నొక్కండి.",
  "Set up classes and sections in Academic Management, then print ID cards class by class.": "అకడమిక్ నిర్వహణలో తరగతులు మరియు సెక్షన్లు సెట్ చేసి, తరగతి వారీగా ID కార్డులు ప్రింట్ చేయండి.",
  "Pick a class. Cards print in batches of up to": "ఒక తరగతి ఎంచుకోండి. కార్డులు ఇన్ని వరకు బ్యాచ్‌లలో ప్రింట్ అవుతాయి:",
