  "Not printed": "ప్రింట్ కాలేదు",
  "Replacement log": "మార్పిడి లాగ్",
  "The certificate fills from the student's record. Preview it, then issue. A TC always goes for approval first": "సర్టిఫికెట్ విద్యార్థి రికార్డ్ నుండి నిండుతుంది. ముందు చూసి, తర్వాత జారీ చేయండి. TC ఎప్పుడూ ముందుగా ఆమోదానికి వెళ్తుంది",
