  "Send consent request": "సమ్మతి అభ్యర్థన పంపండి",
  "Through Parent Link to": "పేరెంట్ లింక్ ద్వారా",
  ", for data and photo consent for each child. They agree with a one-time code to +91": "కు, ప్రతి బిడ్డ డేటా మరియు ఫోటో సమ్మతి కోసం. వారు +91",
  ". Consents already given are left as they are.": "కు వచ్చే ఒక్కసారి కోడ్‌తో సమ్మతిస్తారు. ఇప్పటికే ఇచ్చిన సమ్మతులు అలాగే ఉంటాయి.",
