  "Record consent withdrawal": "సమ్మతి ఉపసంహరణ నమోదు చేయండి",
  "Revoke Parent Link": "పేరెంట్ లింక్ రద్దు చేయండి",
  "Use this when a phone is lost. The old link stops opening at once, and a new link is sent to +91": "ఫోన్ పోయినప్పుడు దీన్ని వాడండి. పాత లింక్ వెంటనే తెరుచుకోవడం ఆగిపోతుంది, కొత్త లింక్ పంపబడుతుంది +91",
  "No documents for this parent. They are added on a child’s Documents tab.": "ఈ తల్లిదండ్రులకు పత్రాలు లేవు. అవి బిడ్డ పత్రాల ట్యాబ్‌లో జోడించబడతాయి.",
  "Custody restrictions are set on each child's link, from the child's profile.": "కస్టడీ పరిమితులు ప్రతి బిడ్డ లింక్‌పై, బిడ్డ ప్రొఫైల్ నుండి సెట్ అవుతాయి.",
  "Keep": "ఉంచండి",
  ") and move another record's children, consent records and documents to it. The other record is archived, not deleted.": ") మరియు మరో రికార్డ్ పిల్లలు, సమ్మతి రికార్డులు మరియు పత్రాలను దీనికి తరలించండి. మరో రికార్డ్ ఆర్కైవ్ అవుతుంది, తొలగించబడదు.",
  "Phone or name": "ఫోన్ లేదా పేరు",
  "Each parent gets a request through Parent Link and agrees with a one-time code sent to their registered mobile. Staff never tick consent for a parent. Consents already given are left as they are.": "ప్రతి తల్లిదండ్రులకు పేరెంట్ లింక్ ద్వారా అభ్యర్థన వస్తుంది, వారి నమోదైన మొబైల్‌కు వచ్చే ఒక్కసారి కోడ్‌తో సమ్మతిస్తారు. సిబ్బంది ఎప్పుడూ తల్లిదండ్రుల తరఫున సమ్మతి టిక్ చేయరు. ఇప్పటికే ఇచ్చిన సమ్మతులు అలాగే ఉంటాయి.",
  "Parents of a section": "ఒక సెక్షన్ తల్లిదండ్రులు",
  "Choose section": "సెక్షన్ ఎంచుకోండి",
  "Every parent": "ప్రతి తల్లిదండ్రులు",
  "Choose another section.": "మరో సెక్షన్ ఎంచుకోండి.",
  "still": "ఇంకా",
  "a consent not given.": "ఒక సమ్మతి ఇవ్వలేదు.",
  "Everyone here has already given consent. Nothing to send.": "ఇక్కడ అందరూ ఇప్పటికే సమ్మతి ఇచ్చారు. పంపడానికి ఏమీ లేదు.",
  "They get data and photo consent requests for each of their children through Parent Link.": "వారికి పేరెంట్ లింక్ ద్వారా ప్రతి బిడ్డకు డేటా మరియు ఫోటో సమ్మతి అభ్యర్థనలు వస్తాయి.",
  "Check the number, or": "నంబర్ తనిఖీ చేయండి, లేదా",
  "add a new parent": "కొత్త తల్లిదండ్రులను జోడించండి",
  "A brother's or sister's parent already on record? Use": "అన్న లేదా అక్క తల్లిదండ్రులు ఇప్పటికే నమోదై ఉన్నారా? బదులుగా",
  "Link existing parent": "ఉన్న తల్లిదండ్రులను కలపండి",
  "instead.": "వాడండి.",
  "more": "మరిన్ని",
  "See them in the Student List": "వారిని విద్యార్థుల జాబితాలో చూడండి",
  "Parents with no other child are archived too.": "వేరే పిల్లలు లేని తల్లిదండ్రులు కూడా ఆర్కైవ్ అవుతారు.",
  "students it updated get their earlier values back, except any changed again since.": "ఇది మార్చిన విద్యార్థులకు ముందటి విలువలు తిరిగి వస్తాయి, తర్వాత మళ్ళీ మార్చినవి తప్ప.",
  "The import stays in the history.": "దిగుమతి చరిత్రలో ఉంటుంది.",
