  "Download skipped rows (CSV)": "వదిలేసిన వరుసలు డౌన్‌లోడ్ చేయండి (CSV)",
  "Imports of students show here, and each can be undone.": "విద్యార్థుల దిగుమతులు ఇక్కడ కనిపిస్తాయి, ప్రతిదాన్ని రద్దు చేయవచ్చు.",
  "No checks yet": "ఇంకా తనిఖీలు లేవు",
  "Start leaving": "వెళ్ళిపోవడం ప్రారంభించండి",
  "TC:": "TC:",
  "No clearance checks run yet: fee dues and library books are checked here once Fee Management and Library Management are in use.": "ఇంకా క్లియరెన్స్ తనిఖీలు జరగలేదు: ఫీజు నిర్వహణ మరియు లైబ్రరీ నిర్వహణ వాడుకలోకి వచ్చిన తర్వాత ఫీజు బాకీలు మరియు లైబ్రరీ పుస్తకాలు ఇక్కడ తనిఖీ అవుతాయి.",
  "Student Profile": "విద్యార్థి ప్రొఫైల్",
  ". Settle each one below, or ask for a waiver with a reason.": ". క్రింద ప్రతిదాన్ని పరిష్కరించండి, లేదా కారణంతో మినహాయింపు అడగండి.",
  "Nothing to check yet: fee dues and library books are checked here once Fee Management and Library Management are in use. Clearance passes.": "ఇంకా తనిఖీ చేయడానికి ఏమీ లేదు: ఫీజు నిర్వహణ మరియు లైబ్రరీ నిర్వహణ వాడుకలోకి వచ్చిన తర్వాత ఫీజు బాకీలు మరియు లైబ్రరీ పుస్తకాలు ఇక్కడ తనిఖీ అవుతాయి. క్లియరెన్స్ పాస్ అయింది.",
  "· checked": "· తనిఖీ అయింది",
  ". The waiver goes to Approvals; someone allowed to approve it decides. The check stays pending until then.": ". మినహాయింపు ఆమోదాలకు వెళ్తుంది; ఆమోదించే అనుమతి ఉన్నవారు నిర్ణయిస్తారు. అప్పటివరకు తనిఖీ పెండింగ్‌లో ఉంటుంది.",
  "See in Approvals": "ఆమోదాలలో చూడండి",
  "Issue TC": "TC జారీ చేయండి",
  "The status changes to": "స్థితి ఇలా మారుతుంది",
  "from": "నుండి",
  ". The record stays, and the student no longer shows in class lists.": ". రికార్డ్ ఉంటుంది, విద్యార్థి ఇక తరగతి జాబితాలలో కనిపించరు.",
  "The status changes by itself on": "స్థితి దానంతట అదే ఈ తేదీన మారుతుంది:",
  "stays in the class. A TC that is waiting for approval is cancelled too.": "తరగతిలో ఉంటారు. ఆమోదం కోసం వేచి ఉన్న TC కూడా రద్దు అవుతుంది.",
  "Mentor": "మార్గదర్శకుడు",
  "Job board": "ఉద్యోగ బోర్డ్",
  "Graduated students become alumni here. Mark them from the card on this page.": "ఉత్తీర్ణులైన విద్యార్థులు ఇక్కడ పూర్వ విద్యార్థులు అవుతారు. ఈ పేజీలోని కార్డ్ నుండి వారిని గుర్తించండి.",
  "An alumni record is made for each, with the graduation year and the parent's phone. You can add their career and college later.": "ప్రతి ఒక్కరికీ ఉత్తీర్ణ సంవత్సరం మరియు తల్లిదండ్రుల ఫోన్‌తో పూర్వ విద్యార్థి రికార్డ్ తయారవుతుంది. వారి కెరీర్ మరియు కాలేజీ తర్వాత జోడించవచ్చు.",
  "recorded. Add one on an alumnus's record; the receipt is made in Finance, Income.": "నమోదైంది. పూర్వ విద్యార్థి రికార్డ్‌పై ఒకటి జోడించండి; రసీదు ఫైనాన్స్, ఆదాయంలో తయారవుతుంది.",
  "Batch": "బ్యాచ్",
  "donation": "విరాళం",
  "· receipts through Finance, Income": "· రసీదులు ఫైనాన్స్, ఆదాయం ద్వారా",
  "No donations recorded.": "విరాళాలు నమోదు కాలేదు.",
  "Record a donation": "విరాళం నమోదు చేయండి",
  "Not mentoring anyone yet. Link a student on the Alumni page.": "ఇంకా ఎవరికీ మార్గదర్శనం చేయడం లేదు. పూర్వ విద్యార్థుల పేజీలో విద్యార్థిని కలపండి.",
  "posted": "పోస్ట్ చేశారు",
  "How to apply:": "ఎలా దరఖాస్తు చేయాలి:",
  "The post is removed from the board and kept in the records.": "పోస్ట్ బోర్డ్ నుండి తీసివేయబడి రికార్డులలో ఉంచబడుతుంది.",
  "Fee dues, library books and other items are checked first. The TC can be issued when every check is clear. The student's status changes on the last date.": "ముందుగా ఫీజు బాకీలు, లైబ్రరీ పుస్తకాలు మరియు ఇతర వస్తువులు తనిఖీ అవుతాయి. ప్రతి తనిఖీ స్పష్టమైనప్పుడు TC జారీ చేయవచ్చు. విద్యార్థి స్థితి చివరి తేదీన మారుతుంది.",
  "For example the parent's letter. PDF or photo, up to 5 files of 10 MB.": "ఉదాహరణకు తల్లిదండ్రుల లేఖ. PDF లేదా ఫోటో, 10 MB చొప్పున 5 ఫైళ్ళ వరకు.",
  "Download the logins (CSV)": "లాగిన్‌లు డౌన్‌లోడ్ చేయండి (CSV)",
  "Student logins are switched off. Switch them on in": "విద్యార్థి లాగిన్‌లు ఆఫ్‌లో ఉన్నాయి. వీటిని ఇక్కడ ఆన్ చేయండి:",
  "Open existing": "ఉన్నది తెరవండి",
