  "You can undo the batch while nothing is recorded for these students in the new year.": "కొత్త సంవత్సరంలో ఈ విద్యార్థులకు ఏమీ నమోదు కానంత వరకు మీరు బ్యాచ్‌ను రద్దు చేయవచ్చు.",
