  "Student status and allowed changes": "విద్యార్థి స్థితి మరియు అనుమతించిన మార్పులు",
  "Only these changes are offered. Promotion and leaving only on their own pages.": "ఈ మార్పులు మాత్రమే చూపబడతాయి. ప్రమోషన్ మరియు వదిలివెళ్ళడం వాటి సొంత పేజీలలో మాత్రమే.",
