  "For example: Board registration number": "ఉదాహరణకు: బోర్డ్ రిజిస్ట్రేషన్ నంబర్",
  "Remove this type": "ఈ రకాన్ని తీసివేయండి",
  "Leaving reasons and alumni": "వదిలివెళ్ళే కారణాలు మరియు పూర్వ విద్యార్థులు",
  "Leaving reasons, one per line": "వదిలివెళ్ళే కారణాలు, ఒక్కో వరుసలో ఒకటి",
  "“Other” is always offered, with a box to write the reason. Reasons in use can be renamed; past records keep theirs.": "“ఇతర” ఎప్పుడూ చూపబడుతుంది, కారణం రాసే బాక్స్‌తో. వాడుకలో ఉన్న కారణాల పేరు మార్చవచ్చు; పాత రికార్డులు వాటిదే ఉంచుకుంటాయి.",
  "Alumni records (optional)": "పూర్వ విద్యార్థి రికార్డులు (ఐచ్ఛికం)",
  "Alumni list, donations, mentors and the job board.": "పూర్వ విద్యార్థుల జాబితా, విరాళాలు, మార్గదర్శకులు మరియు ఉద్యోగ బోర్డ్.",
  "Versioned per year. Changing it never changes past promotions.": "ప్రతి సంవత్సరానికి వేరే వెర్షన్. దీన్ని మార్చినా గత ప్రమోషన్లు ఎప్పుడూ మారవు.",
  "Pass required to promote": "ప్రమోట్ చేయడానికి ఉత్తీర్ణత అవసరం",
  "From the final result in Examination & Results.": "పరీక్షలు & ఫలితాలలోని తుది ఫలితం నుండి.",
  "Minimum attendance %": "కనీస హాజరు %",
  "Below this, the suggestion is Detain. Leave empty for no minimum.": "దీని కంటే తక్కువైతే, సూచన “నిలిపివేయండి”. కనీసం లేకుంటే ఖాళీగా వదలండి.",
  "Exceptions approved by": "మినహాయింపులు ఆమోదించేవారు",
  "Changes from the suggestion need a reason.": "సూచన నుండి మార్పులకు కారణం అవసరం.",
  "Students with fee dues can be promoted": "ఫీజు బాకీలు ఉన్న విద్యార్థులను ప్రమోట్ చేయవచ్చు",
  "On: dues show as a warning only.": "ఆన్: బాకీలు హెచ్చరికగా మాత్రమే చూపబడతాయి.",
  "Designs live in Settings, Document Designs. Numbers run in a series per type and year, for example BONAFIDE/2026-27/0001.": "డిజైన్‌లు సెట్టింగ్‌లు, డాక్యుమెంట్ డిజైన్‌లలో ఉంటాయి. నంబర్లు ప్రతి రకం మరియు సంవత్సరానికి సిరీస్‌లో నడుస్తాయి, ఉదాహరణకు BONAFIDE/2026-27/0001.",
  "Need approval before issuing": "జారీ చేసే ముందు ఆమోదం అవసరం",
  "A transfer certificate always needs approval, and clearance must be done first.": "బదిలీ సర్టిఫికెట్‌కు ఎప్పుడూ ఆమోదం అవసరం, ముందుగా క్లియరెన్స్ పూర్తి కావాలి.",
  "QR code to verify (optional)": "ధృవీకరణకు QR కోడ్ (ఐచ్ఛికం)",
  "No personal data in the code; the check shows only number, type, date and Valid.": "కోడ్‌లో వ్యక్తిగత సమాచారం లేదు; తనిఖీ నంబర్, రకం, తేదీ మరియు “చెల్లుబాటు” మాత్రమే చూపుతుంది.",
  "Migration certificates (optional)": "మైగ్రేషన్ సర్టిఫికెట్లు (ఐచ్ఛికం)",
  "For students moving between boards or states.": "బోర్డులు లేదా రాష్ట్రాల మధ్య మారే విద్యార్థుల కోసం.",
  "DigiLocker-ready file (optional)": "DigiLockerకు సిద్ధమైన ఫైల్ (ఐచ్ఛికం)",
  "Adds a DigiLocker file on Certificates: the issued certificates with their numbers, student details and APAAR ID, in the columns DigiLocker asks for, to upload in the school's DigiLocker Issuer account.": "సర్టిఫికెట్లలో DigiLocker ఫైల్ జోడిస్తుంది: జారీ చేసిన సర్టిఫికెట్లు వాటి నంబర్లు, విద్యార్థి వివరాలు మరియు APAAR IDతో, DigiLocker అడిగే కాలమ్‌లలో, స్కూల్ DigiLocker Issuer ఖాతాలో అప్‌లోడ్ చేయడానికి.",
  "Photo, name, class, QR code, barcode, academic year and valid-until date always print. The look is set in Settings, Document Designs.": "ఫోటో, పేరు, తరగతి, QR కోడ్, బార్‌కోడ్, విద్యా సంవత్సరం మరియు చెల్లుబాటు తేదీ ఎప్పుడూ ప్రింట్ అవుతాయి. రూపం సెట్టింగ్‌లు, డాక్యుమెంట్ డిజైన్‌లలో సెట్ అవుతుంది.",
  "Also show": "ఇవి కూడా చూపండి",
  "Cards per A4 sheet": "ప్రతి A4 షీట్‌కు కార్డులు",
  "RFID cards (optional)": "RFID కార్డులు (ఐచ్ఛికం)",
  "Records each student's RFID number for attendance devices.": "హాజరు పరికరాల కోసం ప్రతి విద్యార్థి RFID నంబర్ నమోదు చేస్తుంది.",
  "Incident types and points, counselling and career guidance": "సంఘటన రకాలు మరియు పాయింట్లు, కౌన్సెలింగ్ మరియు కెరీర్ మార్గదర్శనం",
  "Behaviour points (optional)": "ప్రవర్తన పాయింట్లు (ఐచ్ఛికం)",
  "Points per type, added up for each student.": "ప్రతి రకానికి పాయింట్లు, ప్రతి విద్యార్థికి కూడబడతాయి.",
