  "They leave the pickup list, cannot be the primary contact, and show in red in Front Office, Student Pickup. The student is taken off their Parent Link (no fees, receipts, consent or PTM booking there), and they get none of the student's messages.": "వారు తీసుకెళ్ళేవారి జాబితా నుండి తొలగిపోతారు, ప్రధాన సంప్రదింపు కాలేరు, ఫ్రంట్ ఆఫీస్, విద్యార్థిని తీసుకెళ్ళడంలో ఎరుపులో కనిపిస్తారు. విద్యార్థి వారి పేరెంట్ లింక్ నుండి తీసివేయబడతారు (అక్కడ ఫీజులు, రసీదులు, సమ్మతి లేదా PTM బుకింగ్ ఉండవు), వారికి విద్యార్థి సందేశాలు ఏవీ రావు.",
  "For example: court order dated 03-02-2026; mother has custody.": "ఉదాహరణకు: 03-02-2026 నాటి కోర్టు ఉత్తర్వు; కస్టడీ తల్లి వద్ద ఉంది.",
  "Needed when the restriction is set, changed or removed. Kept in the history.": "పరిమితి పెట్టినప్పుడు, మార్చినప్పుడు లేదా తీసివేసినప్పుడు అవసరం. చరిత్రలో ఉంచబడుతుంది.",
