  "Admission, class changes, certificates and more show here, newest first.": "అడ్మిషన్, తరగతి మార్పులు, సర్టిఫికెట్లు మరియు మరిన్ని ఇక్కడ కనిపిస్తాయి, తాజావి ముందు.",
  "This record was not found.": "ఈ రికార్డ్ కనబడలేదు.",
  "You can see behaviour records but not report them.": "మీరు ప్రవర్తన రికార్డులు చూడగలరు కానీ నమోదు చేయలేరు.",
  "Choose at least one student.": "కనీసం ఒక విద్యార్థిని ఎంచుకోండి.",
  "Report another": "మరొకటి నమోదు చేయండి",
  "You can see this record but not change it.": "మీరు ఈ రికార్డ్ చూడగలరు కానీ మార్చలేరు.",
  "Saved.": "సేవ్ అయింది.",
  "Record archived. Points from it were reversed.": "రికార్డ్ ఆర్కైవ్ అయింది. దాని పాయింట్లు వెనక్కి తీసుకోబడ్డాయి.",
  "You can see points but not change them.": "మీరు పాయింట్లు చూడగలరు కానీ మార్చలేరు.",
  "Points must be a whole number, for example 2 or -2.": "పాయింట్లు పూర్ణ సంఖ్య అయి ఉండాలి, ఉదాహరణకు 2 లేదా -2.",
  "Points saved.": "పాయింట్లు సేవ్ అయ్యాయి.",
  "You cannot refer students to counselling.": "మీరు విద్యార్థులను కౌన్సెలింగ్‌కు పంపలేరు.",
  "Choose the student.": "విద్యార్థిని ఎంచుకోండి.",
  "Referred to counselling. The counsellor has been told.": "కౌన్సెలింగ్‌కు పంపబడింది. కౌన్సెలర్‌కు తెలియజేయబడింది.",
  "This case was not found.": "ఈ కేసు కనబడలేదు.",
  "Choose the status.": "స్థితి ఎంచుకోండి.",
  "Case saved.": "కేసు సేవ్ అయింది.",
  "Session recorded.": "సెషన్ నమోదైంది.",
  "You can see career records but not add them.": "మీరు కెరీర్ రికార్డులు చూడగలరు కానీ జోడించలేరు.",
  "Career record added.": "కెరీర్ రికార్డ్ జోడించబడింది.",
  "Choose a field to update.": "మార్చడానికి ఫీల్డ్ ఎంచుకోండి.",
  "Only people who may see restricted details can change this field.": "పరిమిత వివరాలు చూడగల వారు మాత్రమే ఈ ఫీల్డ్ మార్చగలరు.",
  "Choose the students first.": "ముందుగా విద్యార్థులను ఎంచుకోండి.",
  "Choose the section to move them to.": "వారిని తరలించాల్సిన సెక్షన్ ఎంచుకోండి.",
  "Choose a section of your campus.": "మీ క్యాంపస్ సెక్షన్ ఎంచుకోండి.",
  "Choose the photos.": "ఫోటోలు ఎంచుకోండి.",
  "Student logins are switched off in Student Settings.": "విద్యార్థి సెట్టింగ్‌లలో విద్యార్థి లాగిన్‌లు ఆఫ్‌లో ఉన్నాయి.",
  "Print all": "అన్నీ ప్రింట్ చేయండి",
  "This certificate is not waiting for approval.": "ఈ సర్టిఫికెట్ ఆమోదం కోసం వేచి లేదు.",
  "This certificate was not found.": "ఈ సర్టిఫికెట్ కనబడలేదు.",
  "Issued. Print or download the PDF.": "జారీ అయింది. PDF ప్రింట్ లేదా డౌన్‌లోడ్ చేయండి.",
  "Certificate cancelled. Its number is not used again, and the QR check now says Cancelled.": "సర్టిఫికెట్ రద్దు అయింది. దాని నంబర్ మళ్ళీ వాడబడదు, QR తనిఖీ ఇప్పుడు “రద్దు” అని చెబుతుంది.",
  "Give the reason for the reprint.": "మళ్ళీ ప్రింట్‌కు కారణం ఇవ్వండి.",
  "Replacement recorded. The old card is kept on record as replaced.": "మార్పిడి నమోదైంది. పాత కార్డ్ “మార్చబడింది”గా రికార్డులో ఉంటుంది.",
  "RFID cards are switched off in Student Settings.": "విద్యార్థి సెట్టింగ్‌లలో RFID కార్డులు ఆఫ్‌లో ఉన్నాయి.",
  "The RFID number has 4 to 32 letters A to F and digits, as printed on the card.": "RFID నంబర్‌లో A నుండి F అక్షరాలు మరియు అంకెలు, 4 నుండి 32 వరకు ఉంటాయి, కార్డ్‌పై ముద్రించినట్లు.",
  "This RFID card is already given to another student.": "ఈ RFID కార్డ్ ఇప్పటికే మరో విద్యార్థికి ఇవ్వబడింది.",
  "Type the RFID number. To give the student a new card, type the new number.": "RFID నంబర్ టైప్ చేయండి. విద్యార్థికి కొత్త కార్డ్ ఇవ్వడానికి కొత్త నంబర్ టైప్ చేయండి.",
  "Type the RFID number.": "RFID నంబర్ టైప్ చేయండి.",
  "RFID number saved.": "RFID నంబర్ సేవ్ అయింది.",
  "This link was not found.": "ఈ లింక్ కనబడలేదు.",
  "This parent was not found.": "ఈ తల్లిదండ్రులు కనబడలేదు.",
  "This parent was not found, or is not a parent of your students.": "ఈ తల్లిదండ్రులు కనబడలేదు, లేదా మీ విద్యార్థుల తల్లిదండ్రులు కాదు.",
  "Choose a photo (JPG or PNG).": "ఫోటో ఎంచుకోండి (JPG లేదా PNG).",
  "Photo saved.": "ఫోటో సేవ్ అయింది.",
