  "This leaving request is not in progress.": "ఈ వదిలివెళ్ళే అభ్యర్థన ప్రక్రియలో లేదు.",
  "The last date has not come yet. The status changes on the last date.": "చివరి తేదీ ఇంకా రాలేదు. స్థితి చివరి తేదీన మారుతుంది.",
  "Only a leaving request in progress can be cancelled.": "ప్రక్రియలో ఉన్న వదిలివెళ్ళే అభ్యర్థన మాత్రమే రద్దు చేయవచ్చు.",
  "This mentor is already linked to the student.": "ఈ మార్గదర్శకుడు ఇప్పటికే విద్యార్థితో కలపబడ్డారు.",
  "Student logins are switched off (Student Settings, Student logins).": "విద్యార్థి లాగిన్‌లు ఆఫ్‌లో ఉన్నాయి (విద్యార్థి సెట్టింగ్‌లు, విద్యార్థి లాగిన్‌లు).",
  "The Student role is missing. Ask your School Admin to set it up in Settings, Users & Permissions.": "విద్యార్థి పాత్ర లేదు. సెట్టింగ్‌లు, యూజర్లు & అనుమతులలో సెట్ చేయమని మీ స్కూల్ అడ్మిన్‌ను అడగండి.",
  "This promotion was already undone.": "ఈ ప్రమోషన్ ఇప్పటికే రద్దు అయింది.",
  "Some of these students were moved to another section since. Move them back first, or move single students on their Student Profile.": "ఈ విద్యార్థులలో కొందరు అప్పటి నుండి మరో సెక్షన్‌కు తరలించబడ్డారు. ముందుగా వారిని తిరిగి తరలించండి, లేదా ఒక్కొక్క విద్యార్థిని వారి విద్యార్థి ప్రొఫైల్‌లో తరలించండి.",
  "Some leaving students have already left or have a TC. Undo is no longer possible.": "వెళ్ళిపోతున్న కొందరు విద్యార్థులు ఇప్పటికే వెళ్ళిపోయారు లేదా వారికి TC ఉంది. ఇక రద్దు చేయలేము.",
  "This note was already removed.": "ఈ నోట్ ఇప్పటికే తీసివేయబడింది.",
  "Only the person who wrote this note, or a School Admin, can remove it.": "ఈ నోట్ రాసిన వ్యక్తి, లేదా స్కూల్ అడ్మిన్ మాత్రమే దీన్ని తీసివేయగలరు.",
  "Choose one of this student's parents.": "ఈ విద్యార్థి తల్లిదండ్రులలో ఒకరిని ఎంచుకోండి.",
  "This document was already removed.": "ఈ పత్రం ఇప్పటికే తీసివేయబడింది.",
  "Board registration number": "బోర్డ్ రిజిస్ట్రేషన్ నంబర్",
  "UDISE+ student ID": "UDISE+ విద్యార్థి ID",
  "Late to class": "తరగతికి ఆలస్యం",
  "Homework not done": "హోంవర్క్ చేయలేదు",
  "Uniform not proper": "యూనిఫాం సరిగ్గా లేదు",
  "Disrupting the class": "తరగతికి ఆటంకం",
  "Fighting": "గొడవ",
  "Bullying": "బెదిరింపు",
  "Written warning": "లిఖిత హెచ్చరిక",
  "Helping others": "ఇతరులకు సహాయం",
  "Excellence in class": "తరగతిలో అత్యుత్తమం",
  "Prize in a competition": "పోటీలో బహుమతి",
  "Could not find a free admission number. Check the format in Student Settings.": "ఖాళీ అడ్మిషన్ నంబర్ కనబడలేదు. విద్యార్థి సెట్టింగ్‌లలో ఫార్మాట్ తనిఖీ చేయండి.",
  "Choose the class and section.": "తరగతి మరియు సెక్షన్ ఎంచుకోండి.",
  "That parent record was not found. Add the parent again.": "ఆ తల్లిదండ్రుల రికార్డ్ కనబడలేదు. తల్లిదండ్రులను మళ్ళీ జోడించండి.",
  "Roll number starts at 1.": "రోల్ నంబర్ 1 నుండి ప్రారంభమవుతుంది.",
  "A re-admission request for this student is already waiting in Approvals.": "ఈ విద్యార్థికి మళ్ళీ అడ్మిషన్ అభ్యర్థన ఇప్పటికే ఆమోదాలలో వేచి ఉంది.",
  "The student is already in this section.": "విద్యార్థి ఇప్పటికే ఈ సెక్షన్‌లో ఉన్నారు.",
  "Choose a section of this year.": "ఈ సంవత్సరం సెక్షన్ ఎంచుకోండి.",
  "A section change stays in the same class. To move class, use Promotion.": "సెక్షన్ మార్పు అదే తరగతిలో ఉంటుంది. తరగతి మార్చడానికి “తర్వాతి తరగతికి పంపడం” వాడండి.",
  "This change was already undone.": "ఈ మార్పు ఇప్పటికే రద్దు అయింది.",
  "The student has moved again since, so this cannot be undone.": "విద్యార్థి అప్పటి నుండి మళ్ళీ తరలించబడ్డారు, కాబట్టి దీన్ని రద్దు చేయలేము.",
  "The student already has a class this year. Use Change section.": "ఈ సంవత్సరం విద్యార్థికి ఇప్పటికే తరగతి ఉంది. “సెక్షన్ మార్చండి” వాడండి.",
  "This contact was already removed.": "ఈ సంప్రదింపు ఇప్పటికే తీసివేయబడింది.",
  "Finds the student. It is not changed.": "విద్యార్థిని కనుగొంటుంది. ఇది మారదు.",
