  "Question": "ప్రశ్న",
  "type": "రకం",
  "Add a choice": "ఎంపిక జోడించండి",
  "Must be answered": "తప్పనిసరిగా జవాబు ఇవ్వాలి",
  "Add question": "ప్రశ్న జోడించండి",
  "Anonymous answers": "అనామక జవాబులు",
  "Names are not stored with the answers. Only who has answered is kept, for reminders.": "జవాబులతో పేర్లు నిల్వ చేయబడవు. గుర్తుచేతల కోసం ఎవరు జవాబు ఇచ్చారో మాత్రమే ఉంచబడుతుంది.",
  "Nobody has it yet. Change it as needed, then send it. Each person gets their own link.": "ఇది ఇంకా ఎవరి దగ్గరా లేదు. అవసరమైనట్లు మార్చి, తర్వాత పంపండి. ప్రతి వ్యక్తికి సొంత లింక్ వస్తుంది.",
  "No answers to this question.": "ఈ ప్రశ్నకు జవాబులు లేవు.",
  "more in the export": "మరిన్ని ఎగుమతిలో",
  "Each person gets their own link by WhatsApp or email. After sending, the questions cannot be changed.": "ప్రతి వ్యక్తికి WhatsApp లేదా ఈమెయిల్ ద్వారా సొంత లింక్ వస్తుంది. పంపిన తర్వాత ప్రశ్నలు మార్చలేము.",
  "their link again. Those who answered get nothing.": "వారి లింక్ మళ్ళీ. జవాబు ఇచ్చినవారికి ఏమీ రాదు.",
  "No more answers are taken. The answers so far stay.": "ఇక జవాబులు తీసుకోబడవు. ఇప్పటివరకు వచ్చిన జవాబులు ఉంటాయి.",
  "It leaves the Surveys list.": "ఇది సర్వేల జాబితా నుండి తొలగిపోతుంది.",
  "A draft can be changed until it is sent.": "డ్రాఫ్ట్ పంపే వరకు మార్చవచ్చు.",
  "Short questions for parents or staff. Each person answers once, through their own link.": "తల్లిదండ్రులు లేదా సిబ్బంది కోసం చిన్న ప్రశ్నలు. ప్రతి వ్యక్తి తమ సొంత లింక్ ద్వారా ఒకసారి జవాబు ఇస్తారు.",
  "New template": "కొత్త టెంప్లేట్",
  "Show them": "వాటిని చూపండి",
  "They can be saved, but no SMS can be sent from them.": "వాటిని సేవ్ చేయవచ్చు, కానీ వాటి నుండి SMS పంపలేము.",
  "No SMS": "SMS లేదు",
  "Missing": "లేదు",
  "DLT ID missing": "DLT ID లేదు",
  "Add a language": "భాష జోడించండి",
  "Make a new template to change the wording.": "పదాలు మార్చడానికి కొత్త టెంప్లేట్ తయారు చేయండి.",
  "Tap a blank to add it": "ఖాళీని జోడించడానికి దాన్ని ట్యాప్ చేయండి",
  "Preview with sample details": "నమూనా వివరాలతో ముందుచూపు",
  "The text appears here as a parent would see it.": "తల్లిదండ్రులు చూసినట్లు పాఠం ఇక్కడ కనిపిస్తుంది.",
  "A person with no value for a blank is skipped and listed before sending.": "ఖాళీకి విలువ లేని వ్యక్తిని వదిలేసి, పంపే ముందు జాబితాలో చూపబడుతుంది.",
  "DLT template ID missing": "DLT టెంప్లేట్ ID లేదు",
  "DLT ID added": "DLT ID జోడించబడింది",
  "It cannot be chosen for new messages.": "దీన్ని కొత్త సందేశాలకు ఎంచుకోలేము.",
  "This SMS template cannot be used to send SMS. Add the ID from the DLT portal with Edit.": "ఈ SMS టెంప్లేట్‌తో SMS పంపలేము. “మార్చండి”తో DLT పోర్టల్ ID జోడించండి.",
  "A template sent for approval is approved straight away. Connect WhatsApp in Settings to send it to WhatsApp for real.": "ఆమోదానికి పంపిన టెంప్లేట్ వెంటనే ఆమోదించబడుతుంది. నిజంగా WhatsAppకు పంపడానికి సెట్టింగ్‌లలో WhatsApp కనెక్ట్ చేయండి.",
  "Change the wording with Edit and send it again.": "“మార్చండి”తో పదాలు మార్చి మళ్ళీ పంపండి.",
  "Blanks in this template": "ఈ టెంప్లేట్‌లోని ఖాళీలు",
  "None. Everyone gets the same text.": "ఏవీ లేవు. అందరికీ ఒకే పాఠం వస్తుంది.",
  "No text saved yet.": "ఇంకా పాఠం సేవ్ కాలేదు.",
  "· in use": "· వాడుకలో",
  "Used in": "వాడిన చోట",
  "Send for WhatsApp approval": "WhatsApp ఆమోదానికి పంపండి",
  "Check approval status": "ఆమోద స్థితి తనిఖీ చేయండి",
  "It can be chosen for messages again.": "ఇది మళ్ళీ సందేశాలకు ఎంచుకోవచ్చు.",
  "Messages already sent keep their text. You can restore it from the archived list.": "ఇప్పటికే పంపిన సందేశాలు వాటి పాఠం ఉంచుకుంటాయి. ఆర్కైవ్ జాబితా నుండి దీన్ని తిరిగి తీసుకురావచ్చు.",
  "Saving makes a new version of each changed language. Messages already sent keep the version they used.": "సేవ్ చేస్తే మార్చిన ప్రతి భాషకు కొత్త వెర్షన్ తయారవుతుంది. ఇప్పటికే పంపిన సందేశాలు అవి వాడిన వెర్షన్ ఉంచుకుంటాయి.",
  "A ready message format with blanks like": "ఖాళీలతో సిద్ధమైన సందేశ ఫార్మాట్, ఉదాహరణకు",
  ", in each language you use.": ", మీరు వాడే ప్రతి భాషలో.",
  "Only the Principal and School Admin can send an emergency broadcast.": "ప్రిన్సిపాల్ మరియు స్కూల్ అడ్మిన్ మాత్రమే అత్యవసర ప్రసారం పంపగలరు.",
  "Type EMERGENCY to send to everyone chosen, including parents who opted out.": "వద్దన్న తల్లిదండ్రులతో సహా ఎంచుకున్న అందరికీ పంపడానికి EMERGENCY టైప్ చేయండి.",
  "The recipients or cost changed since you checked. Check the new numbers, then send.": "మీరు తనిఖీ చేసిన తర్వాత స్వీకర్తలు లేదా ఖర్చు మారింది. కొత్త సంఖ్యలు తనిఖీ చేసి, పంపండి.",
  "Give the group a name of 2 to 60 characters.": "గ్రూప్‌కు 2 నుండి 60 అక్షరాల పేరు ఇవ్వండి.",
  "Choose who is in the group first.": "ముందుగా గ్రూప్‌లో ఎవరో ఎంచుకోండి.",
  "Date and time": "తేదీ మరియు సమయం",
