  "Read": "చదివారు",
  "Everything sent: by people, by automatic rules and with notices. Open one to see each person’s status.": "పంపినవన్నీ: వ్యక్తులు, ఆటోమేటిక్ నియమాలు మరియు నోటీసులతో. ప్రతి వ్యక్తి స్థితి చూడడానికి ఒకటి తెరవండి.",
  "Only messages you sent. Open one to see each person’s status.": "మీరు పంపిన సందేశాలు మాత్రమే. ప్రతి వ్యక్తి స్థితి చూడడానికి ఒకటి తెరవండి.",
