  "Anyone": "ఎవరైనా",
  "People": "వ్యక్తులు",
  "Automatic rules": "ఆటోమేటిక్ నియమాలు",
  "Parent, student or staff": "తల్లిదండ్రులు, విద్యార్థి లేదా సిబ్బంది",
